    "        clear_output(wait=True)\n",
    "        display(HTML(ui_html))\n",
    "        time.sleep(delay)\n",
    "\n",
    "# सुबह केवल इस फ़ंक्शन को चलाएं:\n",
    "run_morning_master_system(ticks=20, delay=2.5)\n"
