    "                        <div style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; color: #000; font-weight: 900; font-size: 11px; text-align: center; text-shadow: 0 0 2px #fff;\">\n",
    "                            <span>📊 3. PRICE ACTION</span>\n",
